  "scenario": "two people bargaining over a mug",
  "agents": [
    {
      "name": "Alice",
      "role": "seller",
      "goal": "maximize profit from the sale",
      "constraints": ["must accept a price above $5"]
    },
    {
      "name": "Bob",
      "role": "buyer",
      "goal": "minimize cost of the mug",
      "constraints": ["must offer at least $3"]
    }
  ],
  "outcome": {
    "name": "final price",
