    {
      "name": "initial price expectation",
      "hypothesis": "Alice's expectation of the mug's value affects the final price",
      "predicted_direction": "increase",
      "treatment_values": ["$10", "$7", "$5"]
    },
    {
      "name": "buyer's budget constraint",
      "hypothesis": "Bob's maximum willingness to pay affects the final price",
      "predicted_direction": "decrease",
      "treatment_values": ["$15", "$10", "$5"]
    },
    {
      "name": "mug's perceived value",
      "hypothesis": "The perceived value of the mug influences the negotiation outcome",
      "predicted_direction": "increase",
      "treatment_values": ["high", "medium", "low"]
    }
  ],
  "information_scope": {
    "public": ["mug's condition", "mug's market value"],
    "private": [
      {
        "agent": "Alice",
        "information": ["Alice's cost", "Alice's minimum acceptable price"]
      },
      {
        "agent": "Bob",
        "information": ["Bob's maximum budget", "Bob's preferred price"]
      }
    ]
  },
  "interaction": {
    "order": ["Alice", "Bob"],
    "max_turns": 8,
    "stopping_rule": "when both agents agree on a price or reach a maximum number of turns"
  }
}

