      },
      {
        "agent": "Prosecutor",
        "information": ["Internal investigation reports", "Witness credibility assessments", "Prior case outcomes"]
      }
    ]
  },
  "interaction": {
    "order": ["Judge", "Defense Attorney", "Prosecutor"],
    "max_turns": 3,
    "stopping_rule": "The judge makes the final bail decision after considering all inputs"
  }
}

