  "schema_version": "scientist-design-v1",
  "scenario": "A person is interviewing for a job as a lawyer",
  "agents": [
    {
      "name": "Interviewer",
      "role": "Hiring manager",
      "goal": "Assess the candidate's suitability for the legal position",
      "constraints": ["Evaluate based on experience and communication skills"]
    },
    {
      "name": "Candidate",
      "role": "Job applicant",
      "goal": "Demonstrate competence and secure the job",
      "constraints": ["Answer questions clearly and concisely"]
    },
    {
      "name": "Recruiter",
      "role": "HR representative",
      "goal": "Provide information about the firm and role",
      "constraints": ["Share only relevant details about the firm"]
    }
  ],
  "outcome": {
    "name": "Job offer",
    "operationalization": "Whether the candidate receives a formal job offer",
    "measurement_question": "Did the candidate receive a job offer after the interview?",
    "respondent": "Candidate"
  },
  "causes": [
    {
      "name": "Communication clarity",
      "hypothesis": "Better communication skills increase the likelihood of a job offer",
      "predicted_direction": "increase",
      "treatment_values": ["Clear and structured responses", "Unclear and hesitant answers", "Confident but verbose responses"]
    },
    {
      "name": "Legal experience",
      "hypothesis": "More relevant experience increases the chance of a job offer",
      "predicted_direction": "increase",
      "treatment_values": ["Extensive litigation experience", "Limited experience in legal research", "Experience in corporate law"]
    },
    {
      "name": "Confidence level",
      "hypothesis": "Higher confidence during the interview increases the chance of a job offer",
      "predicted_direction": "increase",
      "treatment_values": ["Confident and composed", "Nervous and hesitant", "Confident but overly aggressive"]
    }
  ],
  "information_scope": {
    "public": ["Company background", "Job description", "Interview schedule"],
    "private": [
      {
        "agent": "Interviewer",
        "information": ["Previous interview feedback", "Internal hiring criteria", "Candidate's resume"]
      },
      {
        "agent": "Candidate",
        "information": ["Interview questions in advance", "Company's salary range", "Potential job responsibilities"]
      },
      {
        "agent": "Recruiter",
        "information": ["Firm's hiring timeline", "Internal candidate rankings", "Candidate's interview performance"]
      }
    ]
  },
  "interaction": {
    "order": ["Interviewer", "Candidate", "Recruiter"],
    "max_turns": 3,
    "stopping_rule": "The interaction stops after the recruiter provides feedback on the candidate's performance."
  }
}

