  "schema_version": "scientist-design-v1",
  "scenario": "3 bidders participating in an auction for a piece of art starting at fifty dollars",
  "agents": [
    {
      "name": "Agent A",
      "role": "Conservative Collector",
      "goal": "Maximize profit while minimizing risk",
      "constraints": ["Bids only when confident about the artwork's value"]
    },
    {
      "name": "Agent B",
      "role": "Speculative Investor",
      "goal": "Achieve high returns through strategic bidding",
      "constraints": ["Limits bids to 20% above current price"]
    },
    {
      "name": "Agent C",
      "role": "Art Enthusiast",
      "goal": "Acquire the artwork for personal collection",
      "constraints": ["Bids only if the artwork meets personal criteria"]
    }
  ],
  "outcome": {
    "name": "Final Bid Price",
    "operationalization": "The highest bid submitted by any agent during the auction",
    "measurement_question": "What is the final price paid for the artwork?",
    "respondent": "The auction house"
  },
  "causes": [
    {
      "name": "Bidder Confidence",
      "hypothesis": "Higher confidence in the artwork's value leads to higher bids",
      "predicted_direction": "increase",
      "treatment_values": ["High", "Medium", "Low"]
    },
    {
      "name": "Bidding Strategy",
      "hypothesis": "Aggressive bidding strategies result in higher final prices",
      "predicted_direction": "increase",
      "treatment_values": ["Aggressive", "Moderate", "Conservative"]
    },
    {
      "name": "Artistic Preference",
      "hypothesis": "Preference for the artwork's style increases willingness to pay",
      "predicted_direction": "increase",
      "treatment_values": ["Strong", "Neutral", "Weak"]
    }
  ],
  "information_scope": {
    "public": ["Starting bid", "Current highest bid", "Number of bidders"],
    "private": [
      {
        "agent": "Agent A",
        "information": ["Personal valuation of the artwork", "Risk tolerance level"]
      },
      {
        "agent": "Agent B",
        "information": ["Financial capacity", "Market trend analysis"]
      },
      {
        "agent": "Agent C",
        "information": ["Personal criteria for acquisition", "Emotional value"]
      }
    ]
  },
  "interaction": {
    "order": ["Agent A", "Agent B", "Agent C"],
    "max_turns": 3,
    "stopping_rule": "Auction ends when no further bids are placed"
  }
}

